import { G } from './base.js';
const PATTERNS={"gingham": "data:image/webp;base64,", "flowers": "data:image/webp;base64,"};
const SIZES={"chip": [280, 110], "compact": [200, 150], "circle": [240, 240], "polaroid": [300, 245], "collage": [420, 285], "tower": [300, 460], "banner": [560, 285], "scroll": [820, 225], "poster": [680, 390]};
export const SCHOOL_PATTERNS=Object.entries(SIZES).map(([key,[W,H]])=>{
 const tw=key==='chip'?45:65,fw=key==='chip'?25:38;
 const body=`<defs><pattern id="g" width="${tw}" height="${tw/.391}" patternUnits="userSpaceOnUse"><image href="${PATTERNS.gingham}" width="${tw}" height="${tw/.391}" preserveAspectRatio="none"/></pattern><pattern id="f" width="${fw}" height="${fw/.206}" patternUnits="userSpaceOnUse"><image href="${PATTERNS.flowers}" width="${fw}" height="${fw/.206}" preserveAspectRatio="none"/></pattern></defs><rect width="${W}" height="${H}" fill="#d5e7f0"/><rect width="${W*.62}" height="${H}" fill="url(#g)" opacity=".7"/><rect x="${W*.72}" width="${W*.28}" height="${H}" fill="url(#f)" opacity=".9"/>`;
 return {...G('v10:school-pattern-'+key,'蓝格纹与细碎花底纸','学园底纹',`0 0 ${W} ${H}`,body),hidden:true,styleId:'school'};
});
